using System;using System.Linq;using System.Collections.Generic;using System.Threading;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime
{
 public sealed class AdRewardView:MonoBehaviour
 {
  GameRuntime game;Text notice,header;Transform rows;GameObject confirmation;readonly List<Action> updates=new List<Action>();string signature="",transaction="";CancellationTokenSource cancellation;IRewardedVideoProvider provider;
  public void Initialize(GameRuntime runtime){game=runtime;provider=RewardProviderFactory.Create(runtime);header=WorkshopUIFactory.Label("AdHeader",transform,"",16,60);notice=WorkshopUIFactory.Label("AdNotice",transform,"Produktionsanbieter nicht verfügbar. Ein bestätigtes Werbefrei-Recht erlaubt die originalen direkten Ansprüche; Limits gelten weiter.",14,90);rows=WorkshopUIFactory.Vertical("AdRows",transform).transform;Build();}
  string Signature()=>string.Join("|",PrestigeAutomation.ResearchJobs(game.State).Select(j=>j.key))+":"+game.State.Ads.hasPending+":"+string.Join(",",game.State.Rewards.owned);
  void Update(){if(game==null)return;if(signature!=Signature())Build();header.text=game.State.Retention.gems+" Gems · Belohnungen / Forschung\n"+(PurchaseRules.AdFree(game.State)?"Werbefrei-Recht aktiv":RewardProviderFactory.Message(provider));foreach(var update in updates)update();}
  void Build(){signature=Signature();WorkshopUIFactory.Clear(rows);updates.Clear();if(game.State.Ads.hasPending){string tx=game.State.Ads.pending.id;WorkshopUIFactory.Button("AdCancelPending",rows,"Gespeicherten Auftrag abbrechen",()=>game.Act(s=>AdRewards.Cancel(s,tx)));}foreach(string kind in new[]{"gems","creditDrop"})AddReward(kind,0);foreach(var job in PrestigeAutomation.ResearchJobs(game.State).OrderBy(j=>j.slot)){int index=job.slot;WorkshopUIFactory.Label("AdLab-"+index,rows,"Labor "+(index+1)+" · "+Balance.Research[Game.ResearchIndex(job.id)].Name,16,44);var skip=WorkshopUIFactory.Button("AdGemSkip-"+index,rows,"",()=>Confirm(index));updates.Add(()=>{var q=AdRewards.SkipQuote(game.State,index);skip.GetComponentInChildren<Text>().text="Sofort abschließen · "+q.Cost+" Gems · "+Math.Ceiling(q.Seconds)+" s";skip.interactable=game.Writable&&q.Allowed&&game.State.Retention.gems>=q.Cost;});AddReward("research",index);}WorkshopUIFactory.Label("AdLegacyInfo",rows,"Vorbereitete Altangebote: Creditboost und Komponenten. Diese API-Pfade haben im aktuellen Webshop keine Aktion. Der Produktionsanbieter bleibt auch hier unverfügbar.",14,100);foreach(string kind in new[]{"creditBoost","components"}){string k=kind;var button=WorkshopUIFactory.Button("AdLegacy-"+k,rows,"",()=>Request(k,0));updates.Add(()=>{button.GetComponentInChildren<Text>().text=k+" · "+AdRewards.LegacyRemaining(game.State,k)+" übrig · "+(PurchaseRules.AdFree(game.State)?"ohne Video":RewardProviderFactory.IsReady(provider)?"Video bereit":"Video nicht verfügbar");button.interactable=game.Writable&&transaction==""&&!game.State.Ads.hasPending&&!ChallengeRules.Active(game.State)&&AdRewards.LegacyRemaining(game.State,k)>0&&(k!="components"||game.State.Prestige.resets>0)&&(PurchaseRules.AdFree(game.State)||RewardProviderFactory.IsReady(provider));});}}
  void AddReward(string kind,int index){var button=WorkshopUIFactory.Button("AdClaim-"+kind+"-"+index,rows,"",()=>Request(kind,index));updates.Add(()=>{var q=AdRewards.Quote(game.State,kind,index);button.GetComponentInChildren<Text>().text=(kind=="gems"?"Gems":kind=="creditDrop"?"Credits":"Forschungszeit")+" +"+q.Amount+" · "+q.Remaining+" übrig\n"+(q.Cooldown>0?Math.Ceiling(q.Cooldown/1000)+" s Wartezeit":PurchaseRules.AdFree(game.State)?"Ohne Video abholen":RewardProviderFactory.IsReady(provider)?"Video ansehen":"Video nicht verfügbar");button.GetComponent<LayoutElement>().preferredHeight=72;button.interactable=game.Writable&&q.Allowed&&transaction==""&&!game.State.Ads.hasPending&&(PurchaseRules.AdFree(game.State)||RewardProviderFactory.IsReady(provider));});}
  void Confirm(int index){if(confirmation!=null)Destroy(confirmation);var q=AdRewards.SkipQuote(game.State,index);confirmation=WorkshopUIFactory.Vertical("AdSkipConfirmation",transform);WorkshopUIFactory.Label("AdSkipDetails",confirmation.transform,"Nur Auftrag "+q.Job+"\n"+Math.Ceiling(q.Seconds)+" s · "+q.Cost+" Gems\nBei geändertem Auftrag oder Preis erneut auswählen.",14,100);WorkshopUIFactory.Button("AdSkipConfirm",confirmation.transform,"Für "+q.Cost+" Gems bestätigen",()=>{bool saved=game.Act(s=>AdRewards.BuySkip(s,index,q.Job,q.Cost));notice.text=saved?"Forschung und Kauf gespeichert.":"Auftrag oder Preis geändert. Kein Kauf.";Destroy(confirmation);});WorkshopUIFactory.Button("AdSkipCancel",confirmation.transform,"Abbrechen",()=>Destroy(confirmation));Canvas.ForceUpdateCanvases();game.Content.GetComponentInParent<ScrollRect>().verticalNormalizedPosition=0;}
  async void Request(string kind,int index){if(transaction!=""||(!PurchaseRules.AdFree(game.State)&&!RewardProviderFactory.IsReady(provider))||!game.AcquireRewardRequest())return;string tx="commerce-"+Guid.NewGuid().ToString("N");string job=kind=="research"?AdRewards.SkipQuote(game.State,index).Job:null;if(!game.Act(s=>new[]{"creditBoost","components"}.Contains(kind)?AdRewards.BeginLegacy(s,kind,tx):AdRewards.Begin(s,kind,tx,index,job)))return;if(PurchaseRules.AdFree(game.State)){game.Act(s=>AdRewards.ClaimAdFree(s,tx));notice.text="Direkter Werbefrei-Anspruch verarbeitet und gespeichert. Keine Anzeige abgespielt.";return;}transaction=tx;cancellation=new CancellationTokenSource();var request=cancellation;RewardProviderResult result;try{result=await provider.ShowAsync(kind,tx,request.Token);}catch(OperationCanceledException){result=RewardProviderResult.Cancelled;}catch{result=RewardProviderResult.Failed;}if(game!=null)game.Act(s=>AdRewards.Complete(s,tx,result==RewardProviderResult.Success?"success":"error"));request.Dispose();if(this!=null){cancellation=null;transaction="";notice.text=result==RewardProviderResult.Unavailable?"Keine Werbequelle. Keine Belohnung und kein Limit verbucht.":"Anfrage beendet: "+result;}}
  void OnDisable(){cancellation?.Cancel();if(game!=null&&transaction!="")game.Act(s=>AdRewards.Cancel(s,transaction));}
 }
}
